scripts.cert_verify_review.py:
"""Review-side, library-free certificate verifier (TASK-20260923-c78ddf, J1 (iii)).

Written by the validator from the check list in
AMD-EXP-AUXIN-7e2e3d-20260923-d1d10 change.D7_certificates.independent_verifier,
NOT from any producer code (none exists). Imports the Python standard library
only. It never imports cypari2, sympy, gmpy2 or any PARI/GMP binding.

Certificate JSON format (exported by make_certs.py):
  ECPP:  {"kind": "ecpp", "N": int-str, "steps": [[N, t, s, a4, [x, y]], ...],
          "terminal": {"kind": "pratt", ...}}
  Pratt: {"kind": "pratt", "p": int-str, "a": int-str,
          "factors": [[f, e, <pratt cert of f or null when f == 2>], ...]}
  Composite witness: {"kind": "composite_fermat", "C": int-str, "a": int-str}

Two modes:
  literal  -- exactly the checks the amendment lists.
  strict   -- literal plus gcd(N, 6) == 1 on every ECPP step (a check the
              amendment's list omits; Goldwasser-Kilian/Atkin-Morain assume
              N coprime to 6 for the short Weierstrass model).
"""
import json
import math
import sys


def _inv(a, n):
    a %= n
    g = math.gcd(a, n)
    if g != 1:
        raise ArithmeticError("non-invertible denominator mod N (gcd=%d)" % g)
    return pow(a, -1, n)


def _add(P, Q, a4, n):
    """Affine addition on y^2 = x^3 + a4 x + b over Z/nZ. None is infinity.
    Raises ArithmeticError on a non-invertible denominator."""
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if (x1 - x2) % n == 0:
        if (y1 + y2) % n == 0:
            return None
        if (y1 - y2) % n != 0:
            raise ArithmeticError("x equal but y neither equal nor opposite mod N")
        lam = (3 * x1 * x1 + a4) * _inv(2 * y1, n) % n
    else:
        lam = (y2 - y1) * _inv(x2 - x1, n) % n
    x3 = (lam * lam - x1 - x2) % n
    y3 = (lam * (x1 - x3) - y1) % n
    return (x3, y3)


def _mul(k, P, a4, n):
    R = None
    Q = P
    while k > 0:
        if k & 1:
            R = _add(R, Q, a4, n)
        k >>= 1
        if k:
            Q = _add(Q, Q, a4, n)
    return R


def _least_c4(N):
    """least integer c with c^4 >= N"""
    c = math.isqrt(math.isqrt(N))
    while c ** 4 < N:
        c += 1
    while c > 0 and (c - 1) ** 4 >= N:
        c -= 1
    return c


def verify_pratt(cert, log, depth=0):
    p = int(cert["p"])
    if p == 2:
        return True
    a = int(cert["a"])
    prod = 1
    for f, e, sub in cert["factors"]:
        f = int(f)
        e = int(e)
        prod *= f ** e
    if prod != p - 1:
        log.append("pratt p=%d: factors do not multiply to p-1" % p)
        return False
    if pow(a, p - 1, p) != 1:
        log.append("pratt p=%d: a^(p-1) != 1" % p)
        return False
    for f, e, sub in cert["factors"]:
        f = int(f)
        if pow(a, (p - 1) // f, p) == 1:
            log.append("pratt p=%d: a^((p-1)/%d) == 1" % (p, f))
            return False
        if f == 2:
            continue
        if sub is None or int(sub["p"]) != f:
            log.append("pratt p=%d: factor %d lacks its own certificate" % (p, f))
            return False
        if not verify_pratt(sub, log, depth + 1):
            return False
    return True


def verify_ecpp(cert, log, strict=False):
    steps = cert["steps"]
    N0 = int(cert["N"])
    if not steps:
        log.append("ecpp: empty chain")
        return False
    if int(steps[0][0]) != N0:
        log.append("ecpp: first step N differs from certified N")
        return False
    q = None
    for i, st in enumerate(steps):
        N, t, s, a4, P = int(st[0]), int(st[1]), int(st[2]), int(st[3]), st[4]
        x, y = int(P[0]) % N, int(P[1]) % N
        if q is not None and N != q:
            log.append("ecpp step %d: N != previous q" % i)
            return False
        if strict and math.gcd(N, 6) != 1:
            log.append("ecpp step %d: gcd(N,6) != 1 (strict)" % i)
            return False
        m = N + 1 - t
        if m <= 0 or s <= 0 or m % s != 0:
            log.append("ecpp step %d: s does not divide m" % i)
            return False
        q = m // s
        b = (y * y - x * x * x - a4 * x) % N
        if math.gcd((4 * a4 ** 3 + 27 * b * b) % N, N) != 1:
            log.append("ecpp step %d: gcd(4a^3+27b^2, N) != 1" % i)
            return False
        c = _least_c4(N)
        if not q > (c + 1) ** 2:
            log.append("ecpp step %d: q <= (c+1)^2" % i)
            return False
        try:
            Q = _mul(s, (x, y), a4 % N, N)
        except ArithmeticError as exc:
            log.append("ecpp step %d: [s]P not computable: %s" % (i, exc))
            return False
        if Q is None:
            log.append("ecpp step %d: [s]P is infinity" % i)
            return False
        # [m]P = [q]([s]P) = O, checked as [q-1]Q == -Q with every
        # denominator invertible mod N (exact arithmetic mod N).
        try:
            R = _mul(q - 1, Q, a4 % N, N)
        except ArithmeticError as exc:
            log.append("ecpp step %d: [q-1][s]P not computable: %s" % (i, exc))
            return False
        if R is None or R[0] != Q[0] or (R[1] + Q[1]) % N != 0:
            log.append("ecpp step %d: [m]P is not the point at infinity" % i)
            return False
    term = cert.get("terminal")
    if term is None or int(term["p"]) != q:
        log.append("ecpp: terminal q lacks a Pratt certificate")
        return False
    return verify_pratt(term, log)


def verify_composite(cert, log):
    C = int(cert["C"])
    a = int(cert["a"])
    ok = pow(a, C - 1, C) != 1
    if not ok:
        log.append("composite: a^(C-1) == 1 mod C")
    return ok


def verify(cert, strict=False):
    log = []
    k = cert["kind"]
    if k == "ecpp":
        ok = verify_ecpp(cert, log, strict=strict)
    elif k == "pratt":
        ok = verify_pratt(cert, log)
    elif k == "composite_fermat":
        ok = verify_composite(cert, log)
    else:
        log.append("unknown kind")
        ok = False
    return ok, log


if __name__ == "__main__":
    path = sys.argv[1]
    with open(path) as fh:
        certs = json.load(fh)
    out = {}
    for name, cert in certs.items():
        ok_l, log_l = verify(cert, strict=False)
        ok_s, log_s = verify(cert, strict=True)
        out[name] = {"literal": ok_l, "strict": ok_s, "log": log_l + log_s}
    json.dump(out, sys.stdout, indent=1, sort_keys=True)
    print()

scripts.make_certs.py:
"""Path-A-style certificate PRODUCER for the review (TASK-20260923-c78ddf).

Uses PARI/GP 2.15.4 through cypari2 2.2.0 (installed only under the review
scratch directory) to produce primecert ECPP certificates, and builds Pratt
certificates for primes < 2^64 and for ECPP terminal q from PARI factor() of
p - 1, with the least primitive-root witness a. Exports JSON for the separate
library-free verifier cert_verify_review.py.
"""
import json
import sys

import cypari2

pari = cypari2.Pari()
pari.allocatemem(2 * 10 ** 9)


def pratt(p):
    p = int(p)
    if p == 2:
        return {"kind": "pratt", "p": "2", "a": "1", "factors": []}
    fac = pari.factor(p - 1)
    fs = [(int(fac[0][i]), int(fac[1][i])) for i in range(len(fac[0]))]
    a = 2
    while True:
        if pow(a, p - 1, p) == 1 and all(pow(a, (p - 1) // f, p) != 1 for f, _ in fs):
            break
        a += 1
    return {"kind": "pratt", "p": str(p), "a": str(a),
            "factors": [[str(f), str(e), None if f == 2 else pratt(f)] for f, e in fs]}


def ecpp(N):
    N = int(N)
    if N < 2 ** 64:
        return pratt(N)
    c = pari.primecert(N)
    if c == 0:
        raise ValueError("PARI primecert returned 0 (not prime)")
    ok = int(pari.primecertisvalid(c))
    steps = []
    for st in c:
        steps.append([str(int(st[0])), str(int(st[1])), str(int(st[2])), str(int(st[3])),
                      [str(int(st[4][0])), str(int(st[4][1]))]])
    last = steps[-1]
    m = int(last[0]) + 1 - int(last[1])
    q = m // int(last[2])
    return {"kind": "ecpp", "N": str(N), "steps": steps, "pari_primecertisvalid": ok,
            "pari_version": ".".join(str(x) for x in pari.version()),
            "terminal": pratt(q)}


if __name__ == "__main__":
    # usage: make_certs.py in.json out.json ; in.json = {name: int-str}
    with open(sys.argv[1]) as fh:
        todo = json.load(fh)
    out = {}
    for name, v in todo.items():
        out[name] = ecpp(int(v))
    with open(sys.argv[2], "w") as fh:
        json.dump(out, fh, indent=1, sort_keys=True)
    print("wrote", len(out), "certificates")

scripts.pins.py:
"""J1 (i): follow AMD-EXP-AUXIN-7e2e3d-20260923-d1d10 change.D1_pins literally.

Review computation for TASK-20260923-c78ddf. Python standard library only.
No factoring of any r - 1 or r + 1 is performed anywhere in this script.

For every row: locate the named block and label in the named file, record the
line span (1-based, as stored), the verbatim lines, the radix, parse per the
amendment's rule, and record every point where the text forced a choice.
Then: cross-source equality, family checks, Hasse, the field-prime confounder
check, and a field-prime SUBSTITUTION test on every row.
"""
import hashlib
import html
import json
import math
import re
import sys

REPO = "/home/user/crypto-autoresearcher/"
SPECS = REPO + "inputs/SAFECURVES-20260825/specs/"
SCR = sys.argv[1] if len(sys.argv) > 1 else "."
SRC_EIP_HTML = SCR + "/sources/eips.ethereum.org_EIPS_eip-197"
SRC_EIP_MD = SCR + "/sources/raw.githubusercontent.com_ethereum_EIPs_master_EIPS_eip-197.md"
SRC_CFRG14 = SCR + "/sources/draft-irtf-cfrg-pairing-friendly-curves-14.txt"


def sha(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()


def lines_of(path):
    # LF-only line numbering (as git, grep -n and awk count). The files carry
    # bare CR, NEL (U+0085) and form-feed characters; Python universal-newline
    # or str.splitlines() numbering would give different spans.
    return [x.decode("utf-8", errors="replace") for x in open(path, "rb").read().split(b"\n")]


HEXSET = set("0123456789abcdefABCDEF")


def parse_amendment_rule(text):
    """The amendment's rule, applied literally: remove whitespace and line
    breaks; a 0x prefix or hex-digit groups mean base 16, otherwise base 10.
    Returns (value or None, radix or None, residue_chars)."""
    t = re.sub(r"\s+", "", text)
    if t.lower().startswith("0x"):
        body = t[2:]
        if body and all(c in HEXSET for c in body):
            return int(body, 16), 16, ""
        return None, 16, "".join(sorted(set(c for c in body if c not in HEXSET)))
    if t and all(c.isdigit() for c in t):
        return int(t, 10), 10, ""
    if t and all(c in HEXSET for c in t):
        return int(t, 16), 16, ""
    return None, None, "".join(sorted(set(c for c in t if c not in HEXSET)))


def span_record(path, L, a, b, choices, value_text=None):
    verb = L[a - 1:b]
    txt = value_text if value_text is not None else "\n".join(verb)
    literal_val, literal_radix, residue = parse_amendment_rule(txt)
    return {"file": path.replace(REPO, ""), "first_line": a, "last_line": b,
            "verbatim": verb, "literal_parse": {"value": None if literal_val is None else str(literal_val),
                                                 "radix": literal_radix, "blocking_chars": residue},
            "choices": choices}


def find_line(L, pred, start=0, stop=None):
    stop = len(L) if stop is None else stop
    for i in range(start, stop):
        if pred(L[i]):
            return i
    return None


# ------------------------------------------------------------------ SP 800-186
def sp800_block(L, header, name):
    for i, s in enumerate(L):
        if s.strip() == header:
            win = " ".join(x.strip() for x in L[i:i + 8])
            if name.replace("-", "") in win.replace(" ", "").replace("-", ""):
                return i
    raise KeyError(header)


def sp800_label(L, blk, label):
    """Line index of 'label:' after block start (label alone or followed by text)."""
    return find_line(L, lambda s: re.match(r"^\s*%s\s*:" % re.escape(label), s) is not None, blk)


def sp800_decimal_after(L, i, after_eq=False):
    """Collect a decimal printed value starting at line i (label line). Takes the
    first run of digits (after '=' if after_eq), following trailing-backslash
    continuations to the next non-blank line. Returns (value_str, first, last, lines)."""
    j = i
    text = L[j]
    if after_eq:
        while "=" not in L[j]:
            j += 1
        text = L[j].split("=", 1)[1]
    else:
        text = L[j].split(":", 1)[1]
    first = j + 1
    digits = re.sub(r"[^0-9\\]", "", text)
    if not re.sub(r"\\", "", digits):
        j += 1
        while not L[j].strip():
            j += 1
        first = j + 1
        digits = re.sub(r"[^0-9\\]", "", L[j])
    parts = [digits]
    while parts[-1].endswith("\\"):
        j += 1
        while not L[j].strip():
            j += 1
        parts.append(re.sub(r"[^0-9\\]", "", L[j]))
    last = j + 1
    return "".join(p.rstrip("\\") for p in parts), first, last


def sp800_hex_after(L, i):
    """Collect the '(=0x ... )' hex representation after line i."""
    j = find_line(L, lambda s: "0x" in s, i)
    first = j + 1
    buf = L[j][L[j].index("0x") + 2:]
    while ")" not in buf:
        j += 1
        buf += " " + L[j]
    buf = buf.split(")", 1)[0]
    return re.sub(r"\s+", "", buf), first, j + 1


def sp800_row(L, path, header, name):
    blk = sp800_block(L, header, name)
    out = {}
    # n
    ni = sp800_label(L, blk, "n")
    dec, a, b = sp800_decimal_after(L, ni)
    hx, ha, hb = sp800_hex_after(L, ni)
    out["n_decimal"] = {"value": int(dec), "first_line": a, "last_line": b,
                        "verbatim": L[ni:b], "label_line": ni + 1}
    try:
        out["n_hex"] = {"value": int(hx, 16), "first_line": ha, "last_line": hb, "verbatim": L[ha - 1:hb]}
    except ValueError:
        out["n_hex"] = {"value": None, "first_line": ha, "last_line": hb, "verbatim": L[ha - 1:hb],
                        "note": "hex representation is an expression, not a hex literal"}
    # literal amendment parse of the label line through the last decimal line
    lit = parse_amendment_rule("\n".join(L[ni:b]).split(":", 1)[1])
    out["n_literal_parse_of_decimal_span"] = {"value": None if lit[0] is None else str(lit[0]),
                                              "radix": lit[1], "blocking_chars": lit[2]}
    # p
    pi = sp800_label(L, blk, "p")
    hx, ha, hb = sp800_hex_after(L, pi)
    out["p_hex"] = {"value": int(hx, 16), "first_line": ha, "last_line": hb, "verbatim": L[ha - 1:hb],
                    "label_line": pi + 1}
    # h
    hi = sp800_label(L, blk, "h")
    hv = find_line(L, lambda s: s.strip() != "" and re.sub(r"\s", "", s).isdigit(), hi + 1)
    out["h"] = {"value": int(L[hv].strip()), "label_line": hi + 1, "value_line": hv + 1}
    out["block_line"] = blk + 1
    return out


# ------------------------------------------------------------------ SEC 2 v2
def sec2_block(L, name):
    hits = [i for i, s in enumerate(L) if s.startswith("2.") and s.endswith("RecommendedParameters" + name)]
    body = [i for i in hits if not L[i].endswith(".")]
    return body[-1]


def sec2_label(L, blk, label):
    for i in range(blk, len(L) - 1):
        if L[i].strip() == label:
            j = i + 1
            while not L[j].strip():
                j += 1
            if L[j].strip() == "=":
                return i, j
    raise KeyError(label)


def sec2_hex(L, eq):
    j = eq + 1
    while not L[j].strip():
        j += 1
    first = j
    parts = []
    while L[j].strip() and all(c in HEXSET for c in L[j].strip()):
        parts.append(L[j].strip())
        j += 1
        while j < len(L) and not L[j].strip():
            j += 1
    return "".join(parts), first + 1, j


def sec2_row(L, name):
    blk = sec2_block(L, name)
    out = {"block_line": blk + 1}
    for lab in ("n", "p", "h"):
        li, eq = sec2_label(L, blk, lab)
        hx, a, b = sec2_hex(L, eq)
        out[lab] = {"value": int(hx, 16), "label_line": li + 1, "first_line": a, "last_line": b,
                    "verbatim": L[a - 1:b]}
    return out


# ------------------------------------------------------------------ RFC 5639
def rfc5639_row(L, section, curve):
    blk = find_line(L, lambda s: s.startswith(section + "  Domain Parameters"))
    cid = find_line(L, lambda s: ("Curve-ID: " + curve) in s, blk)
    out = {"section_line": blk + 1, "curve_id_line": cid + 1}
    for lab in ("p", "q", "h"):
        i = find_line(L, lambda s: re.match(r"^\s+%s\s*=" % lab, s) is not None, cid)
        first = i
        txt = L[i].split("=", 1)[1]
        j = i + 1
        if not txt.strip():
            first = i + 1
        while L[j].strip():
            txt += "\n" + L[j]
            j += 1
        val, rad, res = parse_amendment_rule(txt)
        out[lab] = {"value": val, "radix": rad, "first_line": first + 1, "last_line": j,
                    "verbatim": L[first:j], "label_line": i + 1}
    return out


# ------------------------------------------------------------------ expressions
def eval_expr(s):
    """Evaluate a printed expression of + - ^ over decimal and 0x literals."""
    toks = re.findall(r"0x[0-9a-fA-F]+|\d+|\^|\+|-", s.replace(" ", ""))
    def atom(t):
        return int(t, 16) if t.startswith("0x") else int(t)
    vals, ops, i = [], [], 0
    sign = 1
    total = 0
    cur = None
    while i < len(toks):
        t = toks[i]
        if t in "+-":
            if cur is not None:
                total += sign * cur
            sign = 1 if t == "+" else -1
            cur = None
            i += 1
            continue
        v = atom(t)
        if i + 2 < len(toks) + 1 and i + 1 < len(toks) and toks[i + 1] == "^":
            v = v ** atom(toks[i + 2])
            i += 3
        else:
            i += 1
        cur = v
    if cur is not None:
        total += sign * cur
    return total


def main():
    res = {"source_files": {}, "rows": {}, "choices_made": [], "findings": []}
    sp = SPECS + "sp800-186.txt"
    s2 = SPECS + "sec2-v2.txt"
    r56 = SPECS + "rfc5639.txt"
    r77 = SPECS + "rfc7748.txt"
    for p in (sp, s2, r56, r77, SRC_EIP_HTML, SRC_EIP_MD, SRC_CFRG14):
        res["source_files"][p.replace(REPO, "").replace(SCR + "/", "scratch/")] = sha(p)
    LSP, LS2, L56, L77 = lines_of(sp), lines_of(s2), lines_of(r56), lines_of(r77)

    rows = {}
    for rid, hdr, nm, secname in (("NIST-P-224", "3.2.1.2.", "P-224", "secp224r1"),
                                  ("NIST-P-256", "3.2.1.3.", "P-256", "secp256r1"),
                                  ("NIST-P-384", "3.2.1.4.", "P-384", "secp384r1"),
                                  ("NIST-P-521", "3.2.1.5.", "P-521", "secp521r1")):
        a = sp800_row(LSP, sp, hdr, nm)
        b = sec2_row(LS2, secname)
        r_dec = a["n_decimal"]["value"]
        r_hex = a["n_hex"]["value"]
        rows[rid] = {"r": r_dec, "r_decimal_equals_hex": r_dec == r_hex, "p": a["p_hex"]["value"],
                     "h": a["h"]["value"], "primary": a, "cross_source": b,
                     "cross_source_equal": b["n"]["value"] == r_dec,
                     "cross_source_p_equal": b["p"]["value"] == a["p_hex"]["value"]}
    s = sec2_row(LS2, "secp256k1")
    rows["secp256k1"] = {"r": s["n"]["value"], "p": s["p"]["value"], "h": s["h"]["value"], "primary": s}
    # internal consistency only (cannot pin): EXP-CRYPTO-9225d2 is out of read scope, not opened.
    rows["secp256k1"]["cross_source"] = "NOT CHECKED: experiments/EXP-CRYPTO-9225d2/ is outside this card's read_scope; the amendment says it cannot pin"
    for rid, sec, cv in (("brainpoolP256r1", "3.4.", "brainpoolP256r1"), ("brainpoolP384r1", "3.6.", "brainpoolP384r1")):
        b = rfc5639_row(L56, sec, cv)
        rows[rid] = {"r": b["q"]["value"], "p": b["p"]["value"], "h": b["h"]["value"], "primary": b}
    e = sp800_row(LSP, sp, "3.2.3.1.", "Edwards25519")
    ords = [i for i, x in enumerate(L77) if x.strip().startswith("order ")]
    # curve25519 block order line is the first 'order' after 'called "curve25519"'
    c255 = find_line(L77, lambda x: 'called "curve25519"' in x)
    oi = find_line(L77, lambda x: x.strip().startswith("order "), c255)
    r7748 = eval_expr(L77[oi].strip()[len("order"):])
    rows["Ed25519-L"] = {"r": e["n_decimal"]["value"], "p": e["p_hex"]["value"], "h": e["h"]["value"],
                         "primary": e, "cross_source": {"file": "inputs/SAFECURVES-20260825/specs/rfc7748.txt",
                                                         "line": oi + 1, "verbatim": L77[oi], "value": r7748},
                         "cross_source_equal": r7748 == e["n_decimal"]["value"]}
    # BN254-r: EIP-197 (HTML, as named); the .md is a second retrieval for comparison only.
    h = open(SRC_EIP_HTML, encoding="utf-8").read()
    ht = html.unescape(re.sub(r"<[^>]+>", "", h))
    hq = re.findall(r"prime order\s+q\s*=\s*(\d+)", ht)
    hp = re.findall(r"with\s+p\s*=\s*(\d+)", ht)
