    # BN family check: find integer u with 36u^4+36u^3+24u^2+6u+1 = p
    def Pp(u): return 36*u**4 + 36*u**3 + 24*u**2 + 6*u + 1
    def Pr(u): return 36*u**4 + 36*u**3 + 18*u**2 + 6*u + 1
