    tline = find_line(LC, lambda x: re.match(r"^\s+t = ", x) is not None, blk)
    tval = eval_expr(LC[tline].split("=", 1)[1])
    def hexlab(label):
        i = find_line(LC, lambda x: re.match(r"^\s+%s:" % re.escape(label), x) is not None, blk)
        txt = LC[i].split(":", 1)[1]
        j = i + 1
        while LC[j].strip():
