        return parse_amendment_rule(txt)[0], i + 1, j
    rB, ra, rb = hexlab("r"); pB, pa, pb = hexlab("p"); hB, _, _ = hexlab("h")
    u_as_indeterminate = [i + 1 for i, x in enumerate(LC[blk:blk + 40]) if "indeterminates u" in x or "[u] / (u^2 + 1)" in x]
    rows["BLS12-381-r"] = {"r": rB, "p": pB, "h": hB, "primary": {
        "file": "scratch/sources/draft-irtf-cfrg-pairing-friendly-curves-14.txt", "section_line": blk + 1,
        "r_lines": [ra, rb], "p_lines": [pa, pb], "t_line": tline + 1, "t_verbatim": LC[tline],
        "occurrences_of_label_BLS12_381": lab_underscore,
        "u_is_the_GFp2_indeterminate_in_this_block_at_block_offsets": u_as_indeterminate},
        "family_param_t": str(tval), "family_r_with_t": tval**4 - tval**2 + 1 == rB,
        "family_p_with_t": ((tval - 1)**2 * (tval**4 - tval**2 + 1)) % 3 == 0 and (tval - 1)**2 * (tval**4 - tval**2 + 1) // 3 + tval == pB}

    allp = {k: v["p"] for k, v in rows.items()}
    def confounder(rid, r, p_same, h, all_field):
        reasons = []
        if r == p_same or r in all_field.values():
            reasons.append("field_prime")
        if h is not None and not abs(p_same + 1 - h * r) <= 2 * math.isqrt(p_same) + 2:
            reasons.append("hasse")
