        v["substitution_test_p_as_r"] = confounder(rid, v["p"], v["p"], v["h"], allp)
        v["r_equals_own_p"] = v["r"] == v["p"]
    res["rows"] = rows
    res["bit_classes"] = sorted(set(v["bits"] for v in rows.values()))
    return res


def to_jsonable(o):
    if isinstance(o, dict):
        return {k: to_jsonable(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [to_jsonable(x) for x in o]
    if isinstance(o, int) and not isinstance(o, bool):
        return str(o)
    return o


